// Bad example: SQL Injection vulnerability due to improper use of Statement
protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
    String user = request.getParameter("username");
    try {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test");
        Statement stmt = conn.createStatement();
        // Vulnerable: concatenating user input directly into SQL query
        ResultSet rs = stmt.executeQuery("SELECT * FROM users WHERE username = '" + user + "'");
        // ... process result set ...
    } catch (SQLException e) {
        e.printStackTrace();
    }
}
```

***
```java
// Good example: Uses PreparedStatement to prevent SQL Injection
protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
    String user = request.getParameter("username");
    try {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test");
        // Secure: parameterized query with PreparedStatement
        PreparedStatement stmt = conn.prepareStatement("SELECT * FROM users WHERE username = ?");
        stmt.setString(1, user); // Sanitizes input by escaping special characters
        ResultSet rs = stmt.executeQuery();
        // ... process result set ...
    } catch (SQLException e) {
        e.printStackTrace();
    }
}
```

