protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
    String userId = request.getParameter("userId");
    try {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test", "user", "pass");
        Statement stmt = conn.createStatement();
        // Vulnerable: Directly embedding user input in SQL query
        ResultSet rs = stmt.executeQuery("SELECT * FROM users WHERE id = " + userId);
        // ... process result set ...
    } catch (SQLException e) {
        e.printStackTrace();
    }
}
```

***

```java
// Fixed code: Uses PreparedStatement to prevent SQL Injection
protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
    String userId = request.getParameter("userId");
    try {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test", "user", "pass");
        // Safe: Parameterized query separates SQL logic from data
        PreparedStatement stmt = conn.prepareStatement("SELECT * FROM users WHERE id = ?");
        stmt.setString(1, userId); // Input is properly sanitized
        ResultSet rs = stmt.executeQuery();
        // ... process result set ...
    } catch (SQLException e) {
        e.printStackTrace();
    }
}
```
